/* =====================================================
   HYLOOKS v1.2.1 FINAL PRODUCTION LOADER
   Support Multi CDN (Videy / Cloudflare / Bunny / Any HTTPS MP4)
===================================================== */

const HyLooksLoader = (() => {

    const A = s => atob(s);

    const B = s => s.split("").reverse().join("");

    const C = (data, key) => {
        let output = "";

        for (let i = 0; i < data.length; i++) {
            output += String.fromCharCode(
                data.charCodeAt(i) ^
                key.charCodeAt(i % key.length)
            );
        }

        return output;
    };

    function decode(video) {

        if (!video) return "";

        try {

            const raw = A(video.encrypted);

            const reversed = B(raw);

            const url = C(reversed, video.iv);

            // Validasi URL hasil decode
            const parsed = new URL(url);

            if (
                parsed.protocol !== "https:" ||
                !parsed.pathname.toLowerCase().endsWith(".mp4")
            ) {
                console.error("HyLooks: Invalid MP4 URL");
                return "";
            }

            return url;

        } catch (err) {

            console.error("HyLooks Decode Error:", err);

            return "";

        }

    }

    return { decode };

})();
